package org.brightstats.desktop;
import java.util.*;
import javafx.scene.control.*;
import javafx.scene.layout.VBox;
import javafx.stage.Window;
final class PairwiseDialog {
 enum Context { MATRICES, PLS, PLSC, GSCA, SEM }
 record Settings(Context context,int[] columns,boolean bootstrap){Settings{Objects.requireNonNull(context);columns=columns.clone();if(columns.length<1||columns.length>256||Arrays.stream(columns).anyMatch(i->i<0)||Arrays.stream(columns).distinct().count()!=columns.length)throw new IllegalArgumentException("Select 1–256 distinct numeric columns.");if(context==Context.MATRICES&&bootstrap)throw new IllegalArgumentException("Matrix summaries do not provide parameter bootstrap inference.");}public int[] columns(){return columns.clone();}}
 private static Dialog<Settings> dialog(Window owner,List<String> names,Settings current){var dialog=new Dialog<Settings>();dialog.initOwner(owner);dialog.setTitle("Pairwise missing-data estimation");var context=new ComboBox<Context>();context.getItems().setAll(Context.values());context.setValue(current==null?Context.MATRICES:current.context());context.setId("pairwise-context");var variables=new ListView<String>();variables.setId("pairwise-columns");variables.getItems().setAll(names);variables.getSelectionModel().setSelectionMode(SelectionMode.MULTIPLE);if(current==null)variables.getSelectionModel().selectRange(0,Math.min(8,names.size()));else for(int i:current.columns())if(i<names.size())variables.getSelectionModel().select(i);variables.setPrefHeight(180);var bootstrap=new CheckBox("Shared original-case bootstrap");bootstrap.setId("pairwise-bootstrap");bootstrap.setSelected(current!=null&&current.bootstrap());Runnable update=()->{boolean matrix=context.getValue()==Context.MATRICES;variables.setDisable(!matrix);bootstrap.setDisable(matrix);if(matrix)bootstrap.setSelected(false);};context.valueProperty().addListener((o,a,b)->update.run());update.run();var note=UiAppearance.label("Matrices use selected variables; estimators use their configured model indicators. All original source rows are recovered, including cases removed during earlier preparation. Each pair has its own count. MCAR interpretation is required; indefinite matrices are rejected for estimation. No artificial case scores or ordinary incomplete-data likelihood tests are supplied.");note.setWrapText(true);note.setMaxWidth(580);dialog.getDialogPane().setContent(new VBox(10,context,variables,bootstrap,note));dialog.getDialogPane().getButtonTypes().addAll(ButtonType.OK,ButtonType.CANCEL);var ok=dialog.getDialogPane().lookupButton(ButtonType.OK);ok.disableProperty().bind(javafx.beans.binding.Bindings.size(variables.getSelectionModel().getSelectedIndices()).lessThan(1).or(javafx.beans.binding.Bindings.size(variables.getSelectionModel().getSelectedIndices()).greaterThan(256)));dialog.setResultConverter(button->button==ButtonType.OK?new Settings(context.getValue(),variables.getSelectionModel().getSelectedIndices().stream().mapToInt(Integer::intValue).toArray(),bootstrap.isSelected()):null);return dialog;}
 static Optional<Settings> show(Window owner,List<String> names,Settings current){return dialog(owner,names,current).showAndWait();}
 @SuppressWarnings("unchecked") static Settings smoke(Window owner,List<String> names,java.nio.file.Path image)throws Exception{var dialog=dialog(owner,names,null);dialog.show();var variables=(ListView<String>)dialog.getDialogPane().lookup("#pairwise-columns");var context=(ComboBox<Context>)dialog.getDialogPane().lookup("#pairwise-context");var bootstrap=(CheckBox)dialog.getDialogPane().lookup("#pairwise-bootstrap");var ok=(Button)dialog.getDialogPane().lookupButton(ButtonType.OK);variables.getSelectionModel().clearSelection();ok.fire();if(!dialog.isShowing()||dialog.getResult()!=null||!ok.isDisabled())throw new AssertionError("Empty pairwise selection accepted");variables.getSelectionModel().select(0);variables.getSelectionModel().select(2);context.setValue(Context.PLSC);bootstrap.setSelected(true);dialog.getDialogPane().applyCss();dialog.getDialogPane().layout();java.nio.file.Files.deleteIfExists(image);GraphicExport.png(image,dialog.getDialogPane(),1);ok.fire();var selected=dialog.getResult();if(selected==null||selected.context()!=Context.PLSC||!selected.bootstrap()||!Arrays.equals(selected.columns(),new int[]{0,2}))throw new AssertionError("Pairwise dialog changed settings");var many=dialog(owner,java.util.stream.IntStream.range(0,257).mapToObj(i->"X"+i).toList(),null);many.show();((ListView<String>)many.getDialogPane().lookup("#pairwise-columns")).getSelectionModel().selectAll();if(!many.getDialogPane().lookupButton(ButtonType.OK).isDisabled())throw new AssertionError("Oversize pairwise selection enabled");many.close();return selected;}
}
